#include <stdint.h>
#include <stdio.h>
#include <string.h>
#define CASES 10000000u
#define N 36
#define MUTANTS 37
static const int W[N]={350,300,250,200,250,300,350,300,250,300,350,200,350,350,300,400,250,300,300,250,350,200,300,300,200,250,250,150,250,250,350,350,150,250,300,200};
static const uint64_t ALL=(1ULL<<N)-1ULL;
typedef struct{int score;int respected;int first_unmet;} R;
static uint32_t xs(uint32_t *x){*x^=*x<<13;*x^=*x>>17;*x^=*x<<5;return *x;}
static R oracle(uint64_t pass){R r={0,0,-1};for(int i=0;i<N;i++){if(pass&(1ULL<<i))r.score+=W[i];else if(r.first_unmet<0)r.first_unmet=i;}r.respected=(r.score>=9901);return r;}
static R candidate(uint64_t pass){R r={10000,1,-1};uint64_t missing=(~pass)&ALL;for(int i=N-1;i>=0;i--){if(missing&(1ULL<<i)){r.score-=W[i];r.first_unmet=i;}}r.respected=(r.score>=9901);if(!missing)r.first_unmet=-1;return r;}
static int neq(R a,R b){return a.score!=b.score||a.respected!=b.respected||a.first_unmet!=b.first_unmet;}
static uint64_t gen(uint32_t *s,uint32_t i){if(i<N)return ALL&~(1ULL<<i);uint64_t p=ALL;uint32_t fam=xs(s)%12;switch(fam){case 0:p&=~((1ULL<<0)|(1ULL<<2));break;case 1:p&=~((1ULL<<5)|(1ULL<<6));break;case 2:p&=~((1ULL<<9)|(1ULL<<10));break;case 3:p&=~((1ULL<<12)|(1ULL<<13));break;case 4:p&=~((1ULL<<14)|(1ULL<<15));break;case 5:p&=~((1ULL<<17)|(1ULL<<18));break;case 6:p&=~((1ULL<<20)|(1ULL<<23));break;case 7:p&=~((1ULL<<25)|(1ULL<<26));break;case 8:p&=~((1ULL<<29)|(1ULL<<31));break;case 9:p&=~((1ULL<<30)|(1ULL<<31));break;case 10:p&=~((1ULL<<33));break;default:p&=~((1ULL<<34)|(1ULL<<35));break;}int extra=(int)(xs(s)%5);for(int k=0;k<extra;k++)p&=~(1ULL<<(xs(s)%N));if((xs(s)%100)<7)p=ALL;return p;}
int main(void){uint32_t seed=0xC29F411Cu;unsigned long long mismatch=0,unsafe=0,respected=0,nontrivial=0,kills[MUTANTS];memset(kills,0,sizeof(kills));unsigned long long fail[N];memset(fail,0,sizeof(fail));for(uint32_t i=0;i<CASES;i++){uint64_t p=gen(&seed,i);R o=oracle(p),c=candidate(p);if(neq(o,c))mismatch++;if(c.respected&&!o.respected)unsafe++;if(o.respected)respected++;if(p!=ALL)nontrivial++;uint64_t miss=(~p)&ALL;for(int j=0;j<N;j++)if(miss&(1ULL<<j)){fail[j]++;uint64_t mp=p|(1ULL<<j);if(candidate(mp).respected&&!o.respected)kills[j]++;}if(!o.respected&&c.score>=9400)kills[36]++;}int all=1;for(int i=0;i<MUTANTS;i++)if(kills[i]==0)all=0;int coverage=1;for(int i=0;i<N;i++)if(fail[i]==0)coverage=0;printf("{\"schema\":\"ikant-le-c29-ontological-promise-falsification-10m/v2\",\"seed\":\"0xC29F411C\",\"cases\":%u,\"candidate_oracle_mismatches\":%llu,\"unsafe_respected\":%llu,\"respected_witnesses\":%llu,\"nontrivial_cases\":%llu,\"all_atoms_failed_at_least_once\":%s,\"all_mutants_killed\":%s,\"mutants\":%d,\"kills\":[",CASES,mismatch,unsafe,respected,nontrivial,coverage?"true":"false",all?"true":"false",MUTANTS);for(int i=0;i<MUTANTS;i++){if(i)putchar(',');printf("%llu",kills[i]);}printf("],\"atom_failure_counts\":[");for(int i=0;i<N;i++){if(i)putchar(',');printf("%llu",fail[i]);}printf("],\"status\":\"%s\"}\n",(mismatch==0&&unsafe==0&&all&&coverage&&respected>0&&nontrivial>9000000ULL)?"PASS":"FAIL");return(mismatch==0&&unsafe==0&&all&&coverage&&respected>0&&nontrivial>9000000ULL)?0:2;}
